<template><ContentWrap><el-table :data="rows" @row-click="show"><el-table-column prop="id" label="ID"/><el-table-column prop="agentId" label="Agent"/><el-table-column prop="robotId" label="Robot"/><el-table-column prop="channel" label="渠道"/><el-table-column prop="status" label="状态"/></el-table><el-drawer v-model="open" title="对话 Trace"><div v-for="m in detail?.messages||[]" :key="m.id"><el-tag>{{m.role}}</el-tag> {{m.content}}</div></el-drawer></ContentWrap></template><script setup lang="ts">import{onMounted,ref}from'vue';import{AiConversationApi}from'@/api/ai/conversation';const rows=ref<any[]>([]),detail=ref<any>(),open=ref(false);async function load(){rows.value=await AiConversationApi.list()}async function show(r:any){detail.value=await AiConversationApi.get(r.id);open.value=true}onMounted(load)</script>